import React from 'react';
import MapComponent from './components/MapComponent';
import RentPredictor from './components/rent-predictor/RentPredictor'; // Tumhara import sahi hai

function App() {
  return (
    <div style={{ padding: "20px", fontFamily: "sans-serif" }}>
      <h1>PG/HOSTEL BOOKING SYSTEM</h1>
      <p>AI-Powered recommendations with Real-time Maps</p>
      
      {/* YAHAN ADD KIYA HAI AI RENT PREDICTOR */}
      <RentPredictor />

      <hr style={{ margin: "40px 0", border: "1px solid #eee" }} />

      <h3>Demo PG Location (Near MIET)</h3>
      {/* Ye raha tumhara pro MapComponent */}
      <MapComponent 
        lat={28.9731} 
        lng={77.6402} 
        pgName="Sunrise Girls Hostel" 
        rent={8500} 
      />
    </div>
  );
}

export default App;
